import{_ as e,o,c as l,ah as s}from"./chunks/framework.DEbGi21A.js";const g=JSON.parse('{"title":"Neo 主题换肤支持情况分析 Skill 安装与使用","description":"","frontmatter":{},"headers":[],"relativePath":"theme/主题换肤支持情况分析Skill安装使用.md","filePath":"theme/主题换肤支持情况分析Skill安装使用.md"}'),a={name:"theme/主题换肤支持情况分析Skill安装使用.md"};function d(i,t,n,r,c,h){return o(),l("div",null,[...t[0]||(t[0]=[s('<h1 id="neo-主题换肤支持情况分析-skill-安装与使用" tabindex="-1">Neo 主题换肤支持情况分析 Skill 安装与使用 <a class="header-anchor" href="#neo-主题换肤支持情况分析-skill-安装与使用" aria-label="Permalink to &quot;Neo 主题换肤支持情况分析 Skill 安装与使用&quot;">​</a></h1><div class="warning custom-block"><p class="custom-block-title">Beta 状态</p><p>本「Neo 主题换肤支持情况分析 Skill」目前处于 <strong>Beta</strong> 阶段，功能和使用方式仍在持续打磨中。试用过程中发现任何问题，或有改进建议，欢迎随时反馈到 <a href="https://github.com/xsy-neoui/neo-cmp-docs/issues" target="_blank" rel="noreferrer">neo-cmp-docs Issues</a>。</p></div><h2 id="什么是-neo-主题换肤支持情况分析-skill" tabindex="-1">什么是 Neo 主题换肤支持情况分析 Skill <a class="header-anchor" href="#什么是-neo-主题换肤支持情况分析-skill" aria-label="Permalink to &quot;什么是 Neo 主题换肤支持情况分析 Skill&quot;">​</a></h2><p>一套 AI 辅助的<strong>只读分析</strong>工具，帮助你在动手改造之前，先摸清 Neo 平台历史项目的主题换肤「家底」。AI 会扫描项目源码，盘点哪些页面 / 组件已经支持换肤（已使用 Neo 主题 CSS 变量），以及哪些还残留硬编码品牌色，并结合每个组件的功能、类型与项目内使用位置，产出一份《当前项目主题换肤支持情况.md》分析报告。</p><p>它回答两个核心问题：</p><ol><li><strong>哪些页面 / 组件已经支持换肤</strong>，分别用到了哪些 Neo 主题 CSS 变量。</li><li><strong>哪些页面 / 组件尚存硬编码色值</strong>，分别残留了哪些硬编码品牌色。</li></ol><div class="tip custom-block"><p class="custom-block-title">只读分析，不改源码</p><p>本 Skill <strong>全程只读，绝不修改任何源码</strong>，唯一产物是一份 md 分析报告。规则完全内置（CSS 变量清单 + 色值匹配规则 + 忽略规则），不依赖任何其他技能。如果你要真正改造项目（把硬编码色值替换为 CSS 变量），请使用「<a href="./主题换肤Skill安装使用.html">Neo 主题换肤 Skill</a>」。</p></div><p><strong>核心能力</strong>：</p><ul><li>🔍 <strong>已支持换肤盘点</strong>：扫描项目中所有 Neo 主题 CSS 变量（<code>var(--xxx)</code> / <code>rgba(var(--xxx-rgb), a)</code> / <code>getCssVarHex(&#39;--xxx&#39;)</code>）引用，按组件汇总用到的变量分类（品牌色 / 按钮色 / 边框色 / 背景色 / 图标色 / 文本色 / 导航色）与去重后的具体变量列表</li><li>🎯 <strong>蓝色硬编码盘点</strong>：按内置识别规则找出仍在使用硬编码品牌蓝的组件——完全匹配 48 组（主品牌色 33 组 + 次品牌色 15 组）+ 仅以 <code>#0564f5</code> 为基准的 1-2 色阶近似匹配，标注残留色值、匹配类型与建议目标变量</li><li>🎨 <strong>浅蓝背景色盘点</strong>：识别 <code>background</code> / <code>background-color</code>（JSX 为 <code>backgroundColor</code>）上的 11 组浅蓝硬编码色值，建议目标变量 <code>var(--brand-color-tint)</code>；非背景属性上的浅蓝不计入残留</li><li>🔘 <strong>Primary 按钮语义识别</strong>：<code>button-primary</code> / <code>ant-btn-primary</code> / <code>btn-primary</code> / <code>a-Button--primary</code> / <code>btn-conform</code> / <code>add_button</code> / <code>confirm_button</code> / <code>cancel_button</code> 均按 Primary 按钮语义分析，优先给出 <code>--color-button-filled-primary*</code> 系列建议变量</li><li>🧩 <strong>组件元数据分析</strong>：为每个命中的组件读取实现入口，总结 50 字内功能说明，判定组件类型（<code>NeoRegister</code> 注册 → amis 组件；<code>XRegister.CmpDefine</code> 注册 → Neo 2.0 组件；否则未知），并按 <code>type</code> / <code>cmpType</code> 在项目内精确检索使用位置</li><li>📊 <strong>生成分析报告</strong>：在项目根目录输出《当前项目主题换肤支持情况.md》，报告头标注项目名称、仓库地址、所在分支，正文以<strong>组件为最小粒度逐行输出</strong>已支持 / 尚存硬编码两张明细表</li></ul><h2 id="与「主题换肤升级-skill」的区别" tabindex="-1">与「主题换肤升级 Skill」的区别 <a class="header-anchor" href="#与「主题换肤升级-skill」的区别" aria-label="Permalink to &quot;与「主题换肤升级 Skill」的区别&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">对比项</th><th style="text-align:left;">主题换肤支持情况分析 Skill（本文）</th><th style="text-align:left;">主题换肤（升级）Skill</th></tr></thead><tbody><tr><td style="text-align:left;">目的</td><td style="text-align:left;">只读盘点现状，摸清家底</td><td style="text-align:left;">实际改造，替换为 CSS 变量</td></tr><tr><td style="text-align:left;">是否改源码</td><td style="text-align:left;">❌ 全程只读</td><td style="text-align:left;">✅ 会修改源码</td></tr><tr><td style="text-align:left;">产物</td><td style="text-align:left;">《当前项目主题换肤支持情况.md》分析报告</td><td style="text-align:left;">改造后的源码 + 《Neo主题换肤功能升级报告.md》</td></tr><tr><td style="text-align:left;">典型使用时机</td><td style="text-align:left;">改造前评估、验收后复盘</td><td style="text-align:left;">需要让项目支持换肤时</td></tr></tbody></table><blockquote><p>建议流程：先用<strong>本分析 Skill</strong> 摸清现状 → 再用<strong>升级 Skill</strong> 做改造 → 最后再跑一次本分析 Skill 验收复盘。</p></blockquote><h2 id="环境准备" tabindex="-1">环境准备 <a class="header-anchor" href="#环境准备" aria-label="Permalink to &quot;环境准备&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">依赖</th><th style="text-align:left;">说明</th></tr></thead><tbody><tr><td style="text-align:left;">AI 编辑器</td><td style="text-align:left;">CodeBuddy、Kiro、Cursor 等支持 Skills 的 AI 编辑器</td></tr><tr><td style="text-align:left;">项目</td><td style="text-align:left;">待分析的 Neo 平台项目（本地已 clone，且能访问 <code>git</code>）</td></tr><tr><td style="text-align:left;">Node.js</td><td style="text-align:left;">用于运行内置扫描脚本 <code>neoThemeAnalyzer.js</code> 做一次性数据采集（无 Node 环境时可退化为手动 grep 扫描）</td></tr></tbody></table><blockquote><p>本 Skill 直接在 AI 编辑器中运行，通过对源码的扫描与阅读完成分析。内置的扫描脚本仅做只读扫描，不会改动仓库。</p></blockquote><h2 id="安装" tabindex="-1">安装 <a class="header-anchor" href="#安装" aria-label="Permalink to &quot;安装&quot;">​</a></h2><h3 id="手动安装步骤" tabindex="-1">手动安装步骤 <a class="header-anchor" href="#手动安装步骤" aria-label="Permalink to &quot;手动安装步骤&quot;">​</a></h3><ol><li><p><strong>下载技能包</strong>：<a href="/neo-theme-analyze-skill.zip">neo-theme-analyze-skill.zip</a></p></li><li><p><strong>解压并导入</strong>：将 <code>neo-theme-analyze-skill.zip</code> 解压，得到 <code>neo-theme-analyze-skill</code> 目录。</p></li><li><p>根据你使用的 AI 编辑器，将 skill 添加到对应编辑器中。</p></li></ol><h4 id="codebuddy-安装步骤" tabindex="-1">CodeBuddy 安装步骤 <a class="header-anchor" href="#codebuddy-安装步骤" aria-label="Permalink to &quot;CodeBuddy 安装步骤&quot;">​</a></h4><ol><li>在「技能」页面，点击右上角的「+ 添加技能」按钮，选择「上传技能」</li><li>选择解压得到的 <code>neo-theme-analyze-skill</code> 目录，点击「确定」</li><li>安装完成后，在技能列表中可看到「Neo 平台主题换肤支持情况分析」技能</li></ol><h4 id="kiro-安装步骤" tabindex="-1">Kiro 安装步骤 <a class="header-anchor" href="#kiro-安装步骤" aria-label="Permalink to &quot;Kiro 安装步骤&quot;">​</a></h4><ol><li>将 <code>neo-theme-analyze-skill</code> 目录放入 Kiro 的 skills 目录中</li><li>重启 Kiro 或重新加载技能列表</li></ol><h4 id="cursor-安装步骤" tabindex="-1">Cursor 安装步骤 <a class="header-anchor" href="#cursor-安装步骤" aria-label="Permalink to &quot;Cursor 安装步骤&quot;">​</a></h4><ol><li>将 <code>neo-theme-analyze-skill</code> 目录放入项目的 <code>.cursor/skills/</code> 目录下</li><li>重启 Cursor 或重新加载窗口</li></ol><div class="tip custom-block"><p class="custom-block-title">覆盖说明</p><p>若目标目录中已有同名 skill，覆盖式写入即可。</p></div><h2 id="使用方式" tabindex="-1">使用方式 <a class="header-anchor" href="#使用方式" aria-label="Permalink to &quot;使用方式&quot;">​</a></h2><h3 id="触发方式" tabindex="-1">触发方式 <a class="header-anchor" href="#触发方式" aria-label="Permalink to &quot;触发方式&quot;">​</a></h3><p>在 AI 编辑器中打开待分析的 Neo 项目，然后对 AI 说：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&quot;分析当前项目的主题换肤支持情况&quot;</span></span></code></pre></div><p>或使用以下触发短语：</p><ul><li>&quot;分析项目主题换肤支持情况&quot;</li><li>&quot;梳理主题换肤支持情况&quot;</li><li>&quot;盘点主题换肤 / 项目换肤情况分析&quot;</li><li>&quot;主题换肤支持情况分析 / 主题换肤现状分析&quot;</li><li>&quot;分析已支持换肤的组件&quot;</li><li>&quot;分析还有哪些硬编码色&quot;</li><li>&quot;换肤兼容性分析&quot;</li></ul><blockquote><p>若你的真实意图是<strong>改造 / 替换</strong>（让项目支持换肤、升级换肤功能），本 Skill 不负责改造，请改用「<a href="./主题换肤Skill安装使用.html">主题换肤 Skill</a>」。</p></blockquote><h3 id="ai-会做什么" tabindex="-1">AI 会做什么 <a class="header-anchor" href="#ai-会做什么" aria-label="Permalink to &quot;AI 会做什么&quot;">​</a></h3><p>AI 会按照以下五个步骤<strong>严格顺序</strong>执行，最终产出一份分析报告：</p><table tabindex="0"><thead><tr><th style="text-align:left;">步骤</th><th style="text-align:left;">任务</th><th style="text-align:left;">产出</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>0</strong></td><td style="text-align:left;">采集项目关键信息</td><td style="text-align:left;">项目名称、仓库地址、所在分支</td></tr><tr><td style="text-align:left;"><strong>1</strong></td><td style="text-align:left;">扫描「已支持换肤」</td><td style="text-align:left;">已用 CSS 变量的组件清单 + 变量分类与明细</td></tr><tr><td style="text-align:left;"><strong>2</strong></td><td style="text-align:left;">扫描「尚存硬编码色值」</td><td style="text-align:left;">残留硬编码色值的组件清单 + 具体色值</td></tr><tr><td style="text-align:left;"><strong>3</strong></td><td style="text-align:left;">分析组件元数据与使用位置</td><td style="text-align:left;">50 字内功能说明、组件类型、type/cmpType、项目内引用位置</td></tr><tr><td style="text-align:left;"><strong>4</strong></td><td style="text-align:left;">生成报告</td><td style="text-align:left;">项目根目录 <code>当前项目主题换肤支持情况.md</code></td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">全程由 AI 自主完成，没有「交由人工复核」的环节</p><p>脚本产出的功能说明、组件类型、使用位置等都只是<strong>初筛线索</strong>。AI 必须自己读取源码把它们核实并定稿后写入报告，<strong>不得</strong>把不确定项以「待人工复核」「待确认」等占位内容遗留在报告里。</p></div><h4 id="步骤-0-采集项目关键信息" tabindex="-1">步骤 0：采集项目关键信息 <a class="header-anchor" href="#步骤-0-采集项目关键信息" aria-label="Permalink to &quot;步骤 0：采集项目关键信息&quot;">​</a></h4><p>通过只读命令读取 <code>package.json</code> 的 <code>name</code>、<code>git</code> 远程地址、当前分支（及可选的短 commit），写入报告头；任一取不到时如实填「未知」。</p><h4 id="步骤-1-扫描已支持换肤的页面与组件" tabindex="-1">步骤 1：扫描已支持换肤的页面与组件 <a class="header-anchor" href="#步骤-1-扫描已支持换肤的页面与组件" aria-label="Permalink to &quot;步骤 1：扫描已支持换肤的页面与组件&quot;">​</a></h4><p>在源码（<code>*.scss/css/less/tsx/ts/jsx/js</code>，排除 <code>node_modules</code>、测试文件、构建产物）中查找所有 Neo 主题 CSS 变量引用，按 7 大类归组：</p><table tabindex="0"><thead><tr><th style="text-align:left;">分类</th><th style="text-align:left;">变量前缀 / 代表变量</th></tr></thead><tbody><tr><td style="text-align:left;">品牌色</td><td style="text-align:left;"><code>--brand-color</code>、<code>--brand-color-hover</code>、<code>--brand-color-shade</code>、<code>--brand-color-tint</code> …</td></tr><tr><td style="text-align:left;">背景色</td><td style="text-align:left;"><code>--color-bg-brand*</code></td></tr><tr><td style="text-align:left;">边框色</td><td style="text-align:left;"><code>--color-border-brand*</code></td></tr><tr><td style="text-align:left;">图标色</td><td style="text-align:left;"><code>--color-icon-brand*</code>、<code>--color-icon-fill-brand-link</code></td></tr><tr><td style="text-align:left;">文本色</td><td style="text-align:left;"><code>--color-text-brand*</code>、<code>--color-text-brand-link</code></td></tr><tr><td style="text-align:left;">按钮色</td><td style="text-align:left;"><code>--color-button-filled-primary*</code>（含 <code>-color</code> / <code>-secondary</code> 系列）</td></tr><tr><td style="text-align:left;">导航色</td><td style="text-align:left;"><code>--brand-nav-header-*</code></td></tr></tbody></table><p>对每个组件汇总用到的变量分类与去重后的具体变量列表，并归属到组件与所在页面。项目自定义的非主题变量（如 <code>--gap</code>、<code>--radius</code>）不计入。</p><h4 id="步骤-2-扫描尚存硬编码色值" tabindex="-1">步骤 2：扫描尚存硬编码色值 <a class="header-anchor" href="#步骤-2-扫描尚存硬编码色值" aria-label="Permalink to &quot;步骤 2：扫描尚存硬编码色值&quot;">​</a></h4><p>找出「应替换但尚未替换」的残留项，分蓝色与浅蓝两条线：</p><p><strong>蓝色（品牌色）</strong></p><ul><li><strong>完全匹配</strong>：色值命中内置 48 组对照表（主品牌色 33 组 + 次品牌色 15 组，含 6 位 hex、8 位 hex、<code>rgb()</code>、<code>rgba()</code> 各格式）</li><li><strong>近似匹配</strong>：色值仅与<strong>唯一基准色 <code>#0564f5</code></strong> 差异在 1-2 色阶内（单通道差 ≤ 32 且欧氏距离 ≤ 50），报告标注 <code>近似匹配·N色阶</code></li><li><strong>8 位 hex</strong>：按前 6 位判断归属，后 2 位换算 alpha，建议替换为 <code>rgba(var(--xxx-rgb), alpha)</code></li><li>建议目标变量：主品牌色 → <code>var(--brand-color)</code>；次品牌色 → <code>var(--brand-color-hover)</code></li></ul><p><strong>浅蓝（背景色专用）</strong></p><p>以下 11 组浅蓝出现在 <code>background</code> / <code>background-color</code> / <code>backgroundColor</code> 上时计入残留，建议目标变量 <code>var(--brand-color-tint)</code>：</p><p><code>#e6f0fe</code>、<code>#e6f7ff</code>、<code>#e8f0fe</code>、<code>#e8f1ff</code>、<code>#e7f7ff</code>、<code>#eff6ff</code>、<code>#eef2ff</code>、<code>#dcf4ff</code>、<code>#d9f3fb</code>、<code>#eceff8</code>、<code>#edeff2</code>（常见 8 位写法 <code>#edeff280</code>）</p><p>含透明度写法：<code>#edeff280</code> → 建议 <code>rgba(var(--brand-color-tint-rgb), 0.5)</code>；<code>rgba(230, 247, 255, 0.2)</code> → 建议 <code>rgba(var(--brand-color-tint-rgb), 0.2)</code>。</p><blockquote><p>⚠️ 浅蓝<strong>只做完全匹配、不参与近似匹配</strong>（近似匹配的唯一基准 <code>#0564f5</code> 只服务蓝色）；出现在 <code>color</code> / <code>border-color</code> / <code>box-shadow</code> 等<strong>非背景属性</strong>上的浅蓝、以及清单外的浅色（<code>#f0f8ff</code>、<code>#fafcff</code> 等）都<strong>不计入残留</strong>，可记入「合法跳过」区。</p></blockquote><p><strong>Primary 按钮语义识别（强制）</strong></p><p><code>button-primary</code>、<code>ant-btn-primary</code>、<code>btn-primary</code>、<code>a-Button--primary</code>，以及 class 中含 <code>btn-conform</code>、<code>add_button</code>、<code>confirm_button</code>、<code>cancel_button</code> 的按钮，都必须按 Primary 按钮语义分析（这几个不含 <code>primary</code> 字样，最容易漏判），命中的硬编码色优先建议按钮色变量而非普通品牌色：</p><table tabindex="0"><thead><tr><th style="text-align:left;">场景</th><th style="text-align:left;">建议变量</th></tr></thead><tbody><tr><td style="text-align:left;">非白底按钮的 <code>background</code> / <code>background-color</code></td><td style="text-align:left;"><code>--color-button-filled-primary</code> / <code>-hover</code> / <code>-active</code></td></tr><tr><td style="text-align:left;">非白底按钮的 <code>color</code>（字体色）</td><td style="text-align:left;"><code>--color-button-filled-primary-color</code> / <code>-color-hover</code></td></tr><tr><td style="text-align:left;">非白底按钮的 <code>border-color</code> / <code>border</code> 中色值</td><td style="text-align:left;">与 background <strong>同一套背景色变量</strong>（非字体色变量）</td></tr><tr><td style="text-align:left;">白底按钮 / 空心（轮廓）按钮（含 <code>cancel_button</code>）的 <code>color</code> / <code>border-color</code></td><td style="text-align:left;"><code>--color-button-filled-primary</code> 状态系列，背景保持原样</td></tr></tbody></table><blockquote><p><code>add_button</code>（新增）、<code>confirm_button</code>（确认）按实心 Primary 按钮给建议；<code>cancel_button</code>（取消）按空心轮廓按钮给建议。</p></blockquote><p>扫描时会<strong>严格按忽略规则逐项判定并跳过</strong>（详见下文「智能忽略规则」），跳过项不计入「尚存硬编码色值」，但可在报告「合法跳过」区单独记录。</p><h4 id="步骤-3-分析组件功能、类型与使用位置" tabindex="-1">步骤 3：分析组件功能、类型与使用位置 <a class="header-anchor" href="#步骤-3-分析组件功能、类型与使用位置" aria-label="Permalink to &quot;步骤 3：分析组件功能、类型与使用位置&quot;">​</a></h4><p>对步骤 1、2 命中的每个组件：</p><ol><li><strong>功能说明</strong>：读取组件渲染结构、核心 props、事件处理与数据逻辑，用一句中文概括，长度 ≤ 50 字（不臆测、不写实现细节）</li><li><strong>组件类型与注册标识</strong>： <ul><li><code>NeoRegister(...)</code> 注册 → <strong>amis 组件</strong>，取 <code>name</code> 作为 <code>type</code></li><li><code>XRegister.CmpDefine(...)</code> 注册 → <strong>Neo 2.0 组件</strong>，取 <code>cmpType</code></li><li>两者均无 → <strong>未知</strong></li><li>若同一组件同时命中两类注册 → 同时列出两种标识并注明「注册冲突」</li></ul></li><li><strong>使用位置</strong>：按 <code>type</code> / <code>cmpType</code> 在项目内精确检索引用，记录相对路径 + 行号，排除注册声明自身、测试文件与示例；未找到写「未发现」，类型未知或无标识时写「无法按注册标识检索」</li></ol><h4 id="步骤-4-生成分析报告" tabindex="-1">步骤 4：生成分析报告 <a class="header-anchor" href="#步骤-4-生成分析报告" aria-label="Permalink to &quot;步骤 4：生成分析报告&quot;">​</a></h4><p>在<strong>项目根目录</strong>输出 <code>当前项目主题换肤支持情况.md</code>，包含项目关键信息、总体汇总、已支持换肤明细（含逐组件变量明细区）、尚存硬编码色值明细，以及可选的合法跳过项。</p><h3 id="数据采集-优先跑内置扫描器" tabindex="-1">数据采集：优先跑内置扫描器 <a class="header-anchor" href="#数据采集-优先跑内置扫描器" aria-label="Permalink to &quot;数据采集：优先跑内置扫描器&quot;">​</a></h3><p>Skill 要求<strong>优先运行内置扫描器</strong>一次性完成步骤 1~3 的数据采集，再由 AI 逐个读取组件入口核实后撰写报告：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 在项目根目录执行</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/to/neo-theme-analyze-skill/scripts/neoThemeAnalyzer.js</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 指定项目根目录并输出 JSON</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> neoThemeAnalyzer.js</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --root</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./my-app</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --json</span></span></code></pre></div><p>配套脚本：</p><table tabindex="0"><thead><tr><th style="text-align:left;">脚本</th><th style="text-align:left;">作用</th></tr></thead><tbody><tr><td style="text-align:left;"><code>neoThemeAnalyzer.js</code></td><td style="text-align:left;">主扫描器，一次性采集变量引用、硬编码残留、组件元数据</td></tr><tr><td style="text-align:left;"><code>neoThemeColorMatcher.js</code></td><td style="text-align:left;">色值判定引擎，<code>matchBrandColor()</code>（蓝色）/ <code>matchLightBlueTint()</code>（浅蓝）</td></tr><tr><td style="text-align:left;"><code>componentMetadataAnalyzer.js</code></td><td style="text-align:left;">组件注册类型、功能说明候选、使用位置初筛</td></tr></tbody></table><blockquote><p>无 Node 环境时可退化为手动 grep 扫描，但<strong>近似色（与 <code>#0564f5</code> 差 1-2 色阶但不在完全匹配表内）无法用固定 grep 命中</strong>，需要借助 <code>matchBrandColor()</code> 判定，或对可疑蓝色逐一计算 Δ_ch / d。</p><p>脚本产出的是<strong>初筛数据</strong>（功能说明候选、注册类型、使用位置等），AI 会逐个读取组件入口核实并定稿后写入报告，不会直接照抄脚本候选值。</p></blockquote><h2 id="智能忽略规则" tabindex="-1">智能忽略规则 <a class="header-anchor" href="#智能忽略规则" aria-label="Permalink to &quot;智能忽略规则&quot;">​</a></h2><p>扫描尚存硬编码色值时，AI 会按<strong>固定顺序</strong>逐项判定，命中任一规则即判为「合法跳过」，<strong>不计入</strong>尚存硬编码色值（可在报告「合法跳过」区单独记录）：</p><table tabindex="0"><thead><tr><th style="text-align:left;">忽略场景</th><th style="text-align:left;">说明</th></tr></thead><tbody><tr><td style="text-align:left;">① 类名 / 变量名中含色值</td><td style="text-align:left;">如 <code>text-[#0564f5]</code>、<code>bg-[#4e80f5]</code></td></tr><tr><td style="text-align:left;">② 测试文件</td><td style="text-align:left;"><code>*.test.*</code>、<code>*.spec.*</code>、<code>__tests__/</code> 目录</td></tr><tr><td style="text-align:left;">③ 已注释代码（5 类形态）</td><td style="text-align:left;">单行 <code>//</code>；行内 <code>//</code> 之后；单行块注释 <code>/* ... */</code>；<strong>多行块注释中间行</strong>（含以 <code>*</code> 起首的续行，须用状态机跟踪 <code>/*</code> / <code>*/</code> 开合）；JSX 注释 <code>{/* ... */}</code></td></tr><tr><td style="text-align:left;">④ blue 类选择器（含回溯）</td><td style="text-align:left;">class 名含 <code>blue</code>；所属 CSS 选择器向上回溯（含多行、SCSS/Less 嵌套、<code>&amp;</code> 拼接）后含 <code>blue</code> 也跳过</td></tr><tr><td style="text-align:left;">⑤ <strong><code>var()</code> 中备用（回退）色值</strong></td><td style="text-align:left;">如 <code>var(--brand-color, #0564f5)</code>、<code>var(--card-bg, #e6f0fe)</code>、<code>rgba(var(--brand-color-rgb, 5, 100, 245), 0.2)</code>。仅在变量缺失时兜底，不是运行时生效的主题色 → <strong>不计入残留</strong>，蓝色与浅蓝同等适用</td></tr><tr><td style="text-align:left;">⑥ ECharts 属性</td><td style="text-align:left;">图表配置中的色值（ECharts 不支持 <code>var()</code>，需用 <code>getCssVarHex()</code> 方案）。<strong>须读取完整文件上下文向上回溯到最外层 option 对象确认</strong>，不能只看 <code>color:</code> / <code>itemStyle:</code> 等单行属性名</td></tr><tr><td style="text-align:left;">⑦ 颜色数组字面量</td><td style="text-align:left;">色值位于数组内，如 <code>[&#39;#0564f5&#39;, &#39;#4e80f5&#39;]</code></td></tr><tr><td style="text-align:left;">⑧ 取色器对象</td><td style="text-align:left;">色值作为对象属性值，且该对象<strong>所有属性值都是色值</strong> → 认定为调色板对象整体跳过</td></tr><tr><td style="text-align:left;">⑨ SASS/Less 变量名含 <code>blue</code></td><td style="text-align:left;">变量名含 <code>blue</code>（如 <code>$blue-base</code>、<code>@blue-6</code>），对应色值也跳过</td></tr><tr><td style="text-align:left;">⑩ 超阈值非品牌色</td><td style="text-align:left;">与基准色 <code>#0564f5</code> 差异超阈值（单通道差 &gt; 32 或欧氏距离 &gt; 50）</td></tr><tr><td style="text-align:left;">⑪ 浅蓝在非背景属性上</td><td style="text-align:left;"><code>color</code> / <code>border-color</code> / <code>box-shadow</code> / <code>fill</code> / <code>stroke</code> 等属性上的浅蓝不计入残留</td></tr><tr><td style="text-align:left;">⑫ 清单外浅色</td><td style="text-align:left;">不在浅蓝 11 色清单内的浅色（如 <code>#f0f8ff</code>、<code>#fafcff</code>）不计入残留</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">ECharts 判定的三类命中条件</p><p>① 任意层级命中 <code>series: [{ type: &#39;bar&#39; }]</code>、<code>xAxis</code>、<code>yAxis</code>、<code>legend</code>、<code>grid</code>、<code>dataZoom</code>、<code>visualMap</code> 等专有属性；② 祖先 key 链含 ECharts 专有 key（如 <code>legend.pageIconColor</code>）；③ 经 <code>define()</code> / <code>export default</code> / <code>module.exports</code> / <code>return</code> 导出且顶层含 ≥2 个 ECharts 顶层 option 键的独立配置模块——<strong>即使不 import echarts、不用 <code>&lt;ReactECharts&gt;</code>、变量不叫 option 也算</strong>。三者任一命中即成立。</p></div><h2 id="报告结构" tabindex="-1">报告结构 <a class="header-anchor" href="#报告结构" aria-label="Permalink to &quot;报告结构&quot;">​</a></h2><p>生成的《当前项目主题换肤支持情况.md》包含以下部分：</p><ol><li><strong>项目关键信息</strong>：项目名称、仓库地址、所在分支（+ 可选 commit、分析日期）</li><li><strong>总体汇总</strong>：扫描文件数、已支持换肤组件数、尚存硬编码色值组件数、命中主题变量总数、残留硬编码色值总数、近似匹配数、合法跳过数</li><li><strong>一、已支持换肤的页面与组件</strong>：以组件为最小粒度逐行输出，含组件名称、功能说明（≤50 字）、组件类型、注册标识、所在页面、文件位置、用到的地方、CSS 变量分类，并附<strong>逐组件的具体变量明细区（1.x）</strong></li><li><strong>二、尚存硬编码色值</strong>：逐组件输出，含组件名称、功能说明、组件类型、注册标识、所在页面、文件位置、用到的地方、残留硬编码色值（标注色系：蓝色 / 浅蓝）、匹配类型、建议目标变量</li><li><strong>三、合法跳过项</strong>（可选）：因忽略规则跳过的硬编码色值及原因</li></ol><h3 id="硬性输出规范" tabindex="-1">硬性输出规范 <a class="header-anchor" href="#硬性输出规范" aria-label="Permalink to &quot;硬性输出规范&quot;">​</a></h3><p>Skill 对报告有一组强制约束，任一不满足即视为未完成分析：</p><ul><li><strong>必须以「组件」为最小粒度逐行输出</strong>，严禁用「<code>components/</code> 目录 120 个文件」这类目录 / 文件计数聚合替代组件明细</li><li><strong>每行每个字段都必须填满真实值</strong>，不得留空、不得用 <code>-</code>、<code>TODO</code>、「待补充」「待人工复核」「待确认」等占位内容</li><li>确实无法判定的字段只能按约定值填写：所在页面「未知」、功能说明「未知（未找到组件实现入口）」、组件类型 / 注册标识「未知」、使用位置「未发现」或「无法按注册标识检索」</li><li><strong>已支持换肤部分必须含逐组件 CSS 变量明细区</strong>，只给大类聚合统计视为不合规</li><li>功能说明必须来自对组件实现的实际阅读，长度 ≤ 50 字；组件类型与注册标识必须来自注册代码证据</li><li>报告内容必须与实际扫描 / 阅读结果一致，不得编造组件、色值或引用位置</li></ul><h3 id="报告样例-节选" tabindex="-1">报告样例（节选） <a class="header-anchor" href="#报告样例-节选" aria-label="Permalink to &quot;报告样例（节选）&quot;">​</a></h3><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## 一、已支持换肤的页面与组件</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">| 组件名称 | 功能说明（≤50字） | 组件类型 | 注册标识 | 所在页面 | 文件位置 | 用到的地方 | CSS 变量分类 |</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">|:--|:--|:--|:--|:--|:--|:--|:--|</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">| UserCard | 展示用户摘要并支持进入详情 | amis 组件 | </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">`type=user-card`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> | Dashboard 页 | src/pages/Dashboard/UserCard.tsx | src/pages/Home/schema.ts:32 | 品牌色、文本色 |</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">| NavBar | 提供全局导航、选中与返回交互 | Neo 2.0 组件 | </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">`cmpType=navBar`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> | 多页面复用 | src/components/NavBar/index.scss | src/pages/Layout/config.ts:18 | 导航色、按钮色 |</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">### 1.1 UserCard 变量明细</span></span>\n<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 品牌色：</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">`--brand-color`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">、</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">`--brand-color-hover`</span></span>\n<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 文本色：</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">`--color-text-brand-link`</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## 二、尚存硬编码色值</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">| 组件名称 | 功能说明（≤50字） | 组件类型 | 注册标识 | 所在页面 | 文件位置 | 残留硬编码色值 | 匹配类型 | 建议目标变量 |</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">|:--|:--|:--|:--|:--|:--|:--|:--|:--|</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">| LoginForm | 提供账号输入、校验与登录提交 | amis 组件 | </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">`type=login-form`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> | 登录页 | src/pages/Login/LoginForm.scss:22 | </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">`#0564f5`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">（蓝色） | 完全匹配 | </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">`var(--brand-color)`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> |</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">| Badge | 展示带状态语义的徽标信息 | 未知 | 未知 | 未知 | src/components/Badge/index.tsx:31 | </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">`#0968f5`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">（蓝色） | 近似匹配·1色阶 | </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">`var(--brand-color)`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> |</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">| InfoPanel | 展示提示信息与操作入口 | Neo 2.0 组件 | </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">`cmpType=infoPanel`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> | 详情页 | src/pages/Detail/panel.scss:14 | </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">`#e6f0fe`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">（浅蓝，background） | 完全匹配 | </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">`var(--brand-color-tint)`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> |</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">| SubmitBtn | 提交表单并反馈提交状态 | amis 组件 | </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">`type=submit-btn`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> | 表单页 | src/components/SubmitBtn/index.scss:9 | </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">`#0564f5`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">（btn-conform 背景） | 完全匹配 | </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">`var(--color-button-filled-primary)`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> |</span></span></code></pre></div><h2 id="典型使用场景" tabindex="-1">典型使用场景 <a class="header-anchor" href="#典型使用场景" aria-label="Permalink to &quot;典型使用场景&quot;">​</a></h2><h3 id="场景-改造前先摸清项目换肤家底" tabindex="-1">场景：改造前先摸清项目换肤家底 <a class="header-anchor" href="#场景-改造前先摸清项目换肤家底" aria-label="Permalink to &quot;场景：改造前先摸清项目换肤家底&quot;">​</a></h3><blockquote><p>你接手一个体量较大的历史项目，不确定前人有没有做过换肤改造，也不清楚还有多少硬编码颜色散落在各处，直接动手改造心里没底。</p></blockquote><p><strong>使用 Skill 后</strong>：</p><ol><li>对 AI 说：&quot;分析当前项目的主题换肤支持情况&quot;</li><li>AI 按顺序执行五个步骤：采集项目信息 → 扫描已支持换肤组件 → 扫描尚存硬编码色值（蓝色 + 浅蓝背景色 + Primary 按钮语义）→ 分析每个组件的功能 / 类型 / 使用位置 → 生成《当前项目主题换肤支持情况.md》</li><li>你拿到一份逐组件的现状清单，清楚看到「已支持 X 个组件、还有 Y 个组件残留硬编码色」，据此评估改造工作量与优先级</li></ol><p><strong>价值</strong>：无需逐文件人工排查，一次对话即可产出结构化现状报告，让改造决策有据可依；改造完成后再跑一次，还能作为验收复盘的依据。</p><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><p><strong>Q: 这个 Skill 会修改我的代码吗？</strong></p><p>不会。本 Skill <strong>全程只读</strong>，只扫描和阅读源码，唯一产物是项目根目录下的《当前项目主题换肤支持情况.md》报告，不会改动任何源码文件。</p><p><strong>Q: 它和「主题换肤 Skill」有什么区别？</strong></p><p>本 Skill 只做<strong>只读盘点分析</strong>，输出现状报告；「<a href="./主题换肤Skill安装使用.html">主题换肤 Skill</a>」才会真正<strong>改造替换</strong>源码。建议先用本 Skill 摸清现状，再用升级 Skill 改造，最后再用本 Skill 验收复盘。</p><p><strong>Q: 什么是近似匹配？</strong></p><p>当源码中的色值与<strong>唯一基准色 <code>#0564f5</code></strong> 差异在 1-2 色阶内（单通道差 ≤ 32 且欧氏距离 ≤ 50）时，Skill 会推断它是主品牌色变体并计入「尚存硬编码色值」，在报告中标注 <code>近似匹配·N色阶</code> 及差异数值，方便你复核确认。近似匹配只与 <code>#0564f5</code> 比较，不与对照表其他色值（含次品牌色）比较。</p><p><strong>Q: 浅蓝色值为什么只在背景属性上算残留？</strong></p><p>浅蓝的对应变量是 <code>var(--brand-color-tint)</code>，语义上就是浅色底色。出现在 <code>color</code>、<code>border-color</code>、<code>box-shadow</code> 等非背景属性上的浅蓝不属于换肤改造范围，因此不计入残留。清单外的浅色也不做近似推断，避免把中性浅灰底色误判成品牌色。</p><p><strong>Q: 为什么 <code>var()</code> 里的色值不算残留？</strong></p><p><code>var(--brand-color, #0564f5)</code> 中逗号后的色值是<strong>备用（回退）值</strong>，只在 CSS 变量未定义时兜底，不是运行时生效的主题色，替换它也没有换肤收益。所以这类色值一律判为合法跳过，蓝色与浅蓝同等适用。</p><p><strong>Q: <code>add_button</code>、<code>cancel_button</code> 这类名字也会被识别吗？</strong></p><p>会。<code>btn-conform</code>、<code>add_button</code>、<code>confirm_button</code>、<code>cancel_button</code> 都不含 <code>primary</code> 字样，但属于 Primary 按钮语义，Skill 会强制识别并按按钮语义给出 <code>--color-button-filled-primary*</code> 建议变量。其中 <code>add_button</code> / <code>confirm_button</code> 按实心按钮处理，<code>cancel_button</code> 按空心轮廓按钮处理（只对 <code>color</code> / <code>border-color</code> 给建议）。</p><p><strong>Q: 组件类型是怎么判定的？</strong></p><p>按注册代码判定：通过 <code>NeoRegister(...)</code> 注册的判为 <strong>amis 组件</strong>，取 <code>name</code> 作为 <code>type</code>；通过 <code>XRegister.CmpDefine(...)</code> 注册的判为 <strong>Neo 2.0 组件</strong>，取 <code>cmpType</code>；两者都没有则为「未知」。若同时命中两类注册，报告会同时列出两种标识并注明「注册冲突」。</p><p><strong>Q: 报告里的「使用位置」是怎么来的？</strong></p><p>AI 会用组件的 <code>type</code> / <code>cmpType</code> 值在项目内精确检索引用（如 <code>type: &#39;user-card&#39;</code>、<code>cmpType=&quot;navBar&quot;</code>），记录相对路径与行号，并排除注册声明自身、测试文件和示例。找不到引用时写「未发现」，类型未知或无标识时写「无法按注册标识检索」。</p><p><strong>Q: 报告里会出现「待人工复核」吗？</strong></p><p>不会。Skill 明确要求 AI 自主完成全部核实工作，报告中的每个字段都必须填满真实值；无法判定时只能填写约定值（「未知」/「未发现」/「无法按注册标识检索」），不允许出现空白、<code>-</code>、<code>TODO</code> 或「待复核」类占位内容。</p><p><strong>Q: 为什么 ECharts 图表里的颜色没被算作硬编码残留？</strong></p><p>ECharts 不支持 <code>var(--css-variable)</code> 写法，Skill 会将图表配置中的色值判为「合法跳过」，不计入尚存硬编码色值。判定时会读取完整文件上下文向上回溯到最外层 option 对象确认。如需图表也响应换肤，请使用 <code>getCssVarHex()</code> 方案。</p><p><strong>Q: 不装 Node.js 能用吗？</strong></p><p>可以，但准确度会下降。内置扫描脚本是 Skill 推荐的数据采集方式；无 Node 环境时 AI 会退化为手动 grep 扫描，而近似色无法被固定 grep 命中，需要 AI 对可疑蓝色逐一计算色差判定，耗时更长也更易漏项。建议尽量装上 Node.js。</p><h2 id="反馈与改进" tabindex="-1">反馈与改进 <a class="header-anchor" href="#反馈与改进" aria-label="Permalink to &quot;反馈与改进&quot;">​</a></h2><p>使用过程中遇到问题或有优化建议，欢迎提交到 <a href="https://github.com/xsy-neoui/neo-cmp-docs/issues" target="_blank" rel="noreferrer">neo-cmp-docs Issues</a>。</p>',110)])])}const k=e(a,[["render",d]]);export{g as __pageData,k as default};
